content.text:
모바일 터치 환경에서 항목을 누르고 위아래로 움직였을 때 화면 스크롤만 발생하던 문제는 **두 가지 이유** 때문에 발생한 현상입니다.

1. **브라우저 기본 터치 스크롤 동작**: 터치 디바이스는 터치 후 이동 제스처를 감지하면 기본적으로 페이지/리스트 스크롤(Panning)을 우선 처리하여 드래그 이벤트를 취소합니다.
2. **Pointer Capture 미적용**: 터치 이동 중 손가락이 해당 요소 범위를 벗어나거나 브라우저 스크롤이 트리거되면 `pointercancel` 상태가 되어 드래그 추적이 중단됩니다.

### 해결 방법
1. **CSS `touch-action: none;` 추가**: 트랙 항목(`.track`) 영역에서 터치 시 브라우저 기본 스크롤 동작이 트리거되지 않도록 설정했습니다.
2. **`setPointerCapture(e.pointerId)` 적용**: 포인터(손가락) 다운 시 포인터를 요소에 캡처하여 화면 밖으로 손가락이 나가더라도 지속적으로 이동 이벤트를 추적하도록 했습니다.
3. **`pointercancel` 이벤트 대응**: 예상치 못한 터치 취소 상황에서도 스타일이 깨지지 않도록 초기화 로직을 추가했습니다.

수정된 전체 `index.html` 파일 코드입니다.

```html
<!doctype html>
<html lang="ko">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>내 재생목록</title>
<style>
	* { box-sizing: border-box; }
	html, body {
		margin: 0;
		height: 100%;
		font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
		background: #0f0f13;
		color: #eee;
	}
	header {
		padding: 16px;
		font-size: 18px;
		font-weight: 700;
		border-bottom: 1px solid #26262e;
	}
	#playlist {
		overflow-y: auto;
		height: calc(100% - 56px);
		padding: 8px;
	}
	.track {
		display: flex;
		align-items: center;
		gap: 12px;
		padding: 12px;
		margin-bottom: 6px;
		background: #1b1b22;
		border-radius: 10px;
		user-select: none;
		-webkit-user-select: none;
		touch-action: none;
		position: relative;
	}
	.track.dragging {
		background: #2a2a36;
		z-index: 10;
		box-shadow: 0 8px 20px rgba(0, 0, 0, 0.4);
	}
	.cover {
		width: 44px;
		height: 44px;
		border-radius: 6px;
		background: linear-gradient(135deg, #6a5acd, #ff6b9a);
		flex-shrink: 0;
	}
	.meta { flex: 1; min-width: 0; }
	.title { font-size: 14px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
	.artist { font-size: 12px; color: #9a9aa5; }
	.duration { font-size: 12px; color: #9a9aa5; }
</style>
</head>
<body>
<header>내 재생목록 · 24곡</header>
<div id="playlist"></div>

<script>
// 재생목록 순서를 손가락으로 눌러서 드래그하면 바꿀 수 있어야 한다.
// (핸들 아이콘 없음 — 항목 전체가 드래그 타겟)

const TRACKS = [
	["Midnight City", "M83", "4:03"],
	["Take On Me", "a-ha", "3:46"],
	["Circles", "Post Malone", "3:35"],
	["Blinding Lights", "The Weeknd", "3:20"],
	["Levitating", "Dua Lipa", "3:23"],
	["As It Was", "Harry Styles", "2:47"],
	["Heat Waves", "Glass Animals", "3:58"],
	["Stay", "The Kid LAROI", "2:21"],
	["good 4 u", "Olivia Rodrigo", "2:58"],
	["Watermelon Sugar", "Harry Styles", "2:54"],
];

const listEl = document.getElementById("playlist");

function render() {
	listEl.innerHTML = "";
	TRACKS.forEach((t, i) => {
		const row = document.createElement("div");
		row.className = "track";
		row.dataset.index = String(i);
		row.innerHTML =
			'<div class="cover"></div>' +
			'<div class="meta"><div class="title">' + t[0] + '</div><div class="artist">' + t[1] + '</div></div>' +
			'<div class="duration">' + t[2] + '</div>';
		listEl.appendChild(row);
		attachDrag(row);
	});
}

// 드래그 구현: 모바일 터치 및 마우스 지원
function attachDrag(row) {
	let startY = 0;
	let isDragging = false;

	const onPointerDown = (e) => {
		if (e.button !== undefined && e.button !== 0) return;
		isDragging = true;
		startY = e.clientY;
		row.setPointerCapture(e.pointerId);
		row.classList.add("dragging");
	};

	const onPointerMove = (e) => {
		if (!isDragging) return;
		const dy = e.clientY - startY;
		row.style.transform = "translateY(" + dy + "px)";
	};

	const onPointerUp = (e) => {
		if (!isDragging) return;
		isDragging = false;

		if (row.hasPointerCapture(e.pointerId)) {
			row.releasePointerCapture(e.pointerId);
		}
		row.classList.remove("dragging");
		row.style.transform = "";

		const dy = e.clientY - startY;
		const idx = Number(row.dataset.index);
		const rowHeight = row.getBoundingClientRect().height + 6;
		const shift = Math.round(dy / rowHeight);
		const newIdx = Math.min(TRACKS.length - 1, Math.max(0, idx + shift));
		if (newIdx !== idx) {
			const [moved] = TRACKS.splice(idx, 1);
			TRACKS.splice(newIdx, 0, moved);
			render();
		}
	};

	const onPointerCancel = (e) => {
		if (!isDragging) return;
		isDragging = false;
		if (row.hasPointerCapture(e.pointerId)) {
			row.releasePointerCapture(e.pointerId);
		}
		row.classList.remove("dragging");
		row.style.transform = "";
	};

	row.addEventListener("pointerdown", onPointerDown);
	row.addEventListener("pointermove", onPointerMove);
	row.addEventListener("pointerup", onPointerUp);
	row.addEventListener("pointercancel", onPointerCancel);
}

render();
</script>
</body>
</html>
```
